#!/usr/bin/env python3
"""Writes the datapack's generated files from a Minecraft version's registries (the game engine spec,
"the datapack"); everything else in engine/datapack/everhear/ is written by hand.

Commands cannot name an entity's type or a block as text, so the datapack numbers them: every entity
type and every block gets an index (1-based, in sorted order; 0 is "not known"), and each bit of the
index is a tag (`#everhear:bit/<k>`). A function tests the bits (eight for entities, eleven for
blocks) and adds them up; the engine reads the tables from `everhear:meta` and turns the number back
into the name. An advancement cannot run a test on the entity it saw, so `hit` and `kill` carry one
criterion per bit and its inverse instead, and the reward reads which were granted.

    python3 engine/datapack/generate.py REGISTRIES_JSON [--mc 26.3]

REGISTRIES_JSON is `reports/registries.json` from the server jar's data generator:

    java -DbundlerMainClass=net.minecraft.data.Main -jar server.jar --reports --output OUT

Run it again for a new Minecraft version, and raise VERSION (vfg_engine.mc.datapack checks it).
"""

import argparse
import json
import os
import shutil
import sys

# The datapack's version: everhear:meta's `version`, which McIo.open checks. Raise it whenever the
# pack changes in a way the engine reads (a storage layout, an event's fields, a function's name).
VERSION = 1

HERE = os.path.dirname(os.path.abspath(__file__))
PACK = os.path.join(HERE, "everhear")
# Every item of the version, for vfg_engine.bases (KNOWN_BASES): the engine's side of the same registry.
ITEMS_PY = os.path.join(os.path.dirname(HERE), "vfg_engine", "mc", "items.py")
DATA = os.path.join(PACK, "data", "everhear")

GENERATED_NOTE = "# Generated by engine/datapack/generate.py from Minecraft %s's registries: do not edit.\n"


def bits_for(n):
    """How many bits number 1..n (0 stays free for "not known")."""
    return max(1, n.bit_length())


def write(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def write_json(path, doc):
    write(path, json.dumps(doc, indent=2) + "\n")


def snbt_list(names):
    return "[" + ",".join(json.dumps(n) for n in names) + "]"


def bit_tags(kind, names, nbits):
    """One tag per bit: the names whose index (1-based) has that bit set."""
    folder = os.path.join(DATA, "tags", kind, "bit")
    shutil.rmtree(folder, ignore_errors=True)
    for k in range(nbits):
        values = [name for i, name in enumerate(names, start=1) if i >> k & 1]
        write_json(os.path.join(folder, "%d.json" % k), {"values": values})


def type_function(path, mc, nbits, test, score, about):
    lines = [GENERATED_NOTE % mc, "# %s\n" % about, "scoreboard players set %s everhear.t 0\n" % score]
    for k in range(nbits):
        lines.append("execute if %s run scoreboard players add %s everhear.t %d\n"
                     % (test % k, score, 1 << k))
    write(path, "".join(lines))


def bit_criteria(trigger, base, nbits):
    """Criteria b<k> (the entity's type has bit k) and n<k> (it has not), each also meeting `base`;
    the requirements need one of each pair, so the reward runs once every bit is known."""
    criteria, requirements = {}, []
    for k in range(nbits):
        # 26.3's forms: a trigger's `entity` is one loot condition, which names its kind under
        # "type", and an entity predicate's parts are keyed "minecraft:<part>".
        test = {"type": "minecraft:entity_properties", "entity": "this",
                "predicate": {"minecraft:entity_type": "#everhear:bit/%d" % k}}
        has = dict(base, entity=test)
        hasnt = dict(base, entity={"type": "minecraft:inverted", "term": test})
        criteria["b%d" % k] = {"trigger": trigger, "conditions": has}
        criteria["n%d" % k] = {"trigger": trigger, "conditions": hasnt}
        requirements.append(["b%d" % k, "n%d" % k])
    return criteria, requirements


def advancement_type_function(path, mc, adv, nbits):
    lines = [GENERATED_NOTE % mc,
             "# The type of the entity everhear:%s saw, from the criteria it granted, into #y.\n" % adv,
             "scoreboard players set #y everhear.t 0\n"]
    for k in range(nbits):
        lines.append("execute if entity @s[advancements={everhear:%s={b%d=true}}] run scoreboard players "
                     "add #y everhear.t %d\n" % (adv, k, 1 << k))
    write(path, "".join(lines))


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("registries", help="reports/registries.json from the server jar's data generator")
    ap.add_argument("--mc", default="26.3", help="the Minecraft version it came from (default 26.3)")
    args = ap.parse_args(argv)
    with open(args.registries, encoding="utf-8") as f:
        reg = json.load(f)
    types = sorted(reg["minecraft:entity_type"]["entries"])
    blocks = sorted(reg["minecraft:block"]["entries"])
    tbits, bbits = bits_for(len(types)), bits_for(len(blocks))

    bit_tags("entity_type", types, tbits)
    bit_tags("block", blocks, bbits)
    type_function(os.path.join(DATA, "function", "type", "entity.mcfunction"), args.mc, tbits,
                  "entity @s[type=#everhear:bit/%d]", "#y",
                  "@s's type as its index in everhear:meta types, into #y (0: a type this pack does not know).")
    type_function(os.path.join(DATA, "function", "type", "block.mcfunction"), args.mc, bbits,
                  "block ~ ~ ~ #everhear:bit/%d", "#b",
                  "The block here as its index in everhear:meta blocks, into #b (0: a block this pack does not know).")

    melee = {"damage": {"type": {"is_direct": True}}}
    for adv, trigger, base, reward, about in (
            ("hit", "minecraft:player_hurt_entity", melee, "everhear:ev/hit",
             "A player hit an entity in melee (the damage's direct source is the player)."),
            ("kill", "minecraft:player_killed_entity", {}, "everhear:ev/kill",
             "A player killed an entity.")):
        criteria, requirements = bit_criteria(trigger, base, tbits)
        write_json(os.path.join(DATA, "advancement", adv + ".json"), {
            "criteria": criteria, "requirements": requirements,
            "rewards": {"function": reward}, "sends_telemetry_event": False,
            "__comment": about + " Generated by engine/datapack/generate.py; the reward reads the bits."})
        advancement_type_function(os.path.join(DATA, "function", "ev", adv + "_type.mcfunction"), args.mc, adv, tbits)

    write(os.path.join(DATA, "function", "meta.mcfunction"), "".join([
        GENERATED_NOTE % args.mc,
        "# What the engine checks and reads at open(): this pack's version, the Minecraft version it was\n",
        "# made for, and the tables that turn a type's or a block's index back into its name.\n",
        "data modify storage everhear:meta version set value %d\n" % VERSION,
        "data modify storage everhear:meta mc set value %s\n" % json.dumps(args.mc),
        "data modify storage everhear:meta types set value %s\n" % snbt_list([""] + types),
        "data modify storage everhear:meta blocks set value %s\n" % snbt_list([""] + blocks),
    ]))
    items = sorted(i for i in reg["minecraft:item"]["entries"] if i != "minecraft:air")
    lines = ['"""Every item in Minecraft %s, the bases an EverHear item may be made on (vfg_engine.bases).\n\n'
             'Generated by engine/datapack/generate.py from the server jar\'s registries: do not edit."""\n\n'
             % args.mc, "MC = %s\n\n" % json.dumps(args.mc), "ITEMS = frozenset({\n"]
    lines += ["    %s,\n" % json.dumps(i) for i in items]
    lines.append("})\n")
    write(ITEMS_PY, "".join(lines))
    print("generate: %d entity types (%d bits), %d blocks (%d bits), %d items, version %d"
          % (len(types), tbits, len(blocks), bbits, len(items), VERSION))
    return 0


if __name__ == "__main__":
    sys.exit(main())
